#include <vector>
#include <iostream>

int main() {
    std::vector<int> v1 = {1, 5, 10};
    std::vector<int> v2 = {1, 5, 20};
    std::vector<int> v3 = {1, 5};

    // Lexicographical comparison: 10 < 20 at index 2
    std::cout << "v1 < v2: " << (v1 < v2) << " (True)\n";

    // Shorter is less than longer if prefix matches
    std::cout << "v3 < v1: " << (v3 < v1) << " (True)\n";

    return 0;
}
